import { test, before, after } from "node:test";
import assert from "node:assert/strict";
import { createBookingService } from "../src/booking/service.js";
import { createServer } from "../src/booking/server.js";

const events = new Map([["e1", { seats: ["A1", "A2", "B1"] }]]);
let service;
let server;
let base;

before(async () => {
  service = createBookingService(events);
  const real = service.holdSeat;
  service.holdSeat = (eventId, seat, customer) => {
    if (customer === "explode") throw new TypeError("secret internal detail: db password");
    return real(eventId, seat, customer);
  };
  server = createServer(service);
  await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
  base = `http://127.0.0.1:${server.address().port}`;
});

after(async () => {
  server.closeAllConnections();
  await new Promise((resolve) => server.close(resolve));
});

async function post(path, body, raw) {
  const res = await fetch(base + path, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: raw ?? JSON.stringify(body),
    signal: AbortSignal.timeout(3000),
  });
  return { status: res.status, json: await res.json() };
}

test("a free seat is held: 201", async () => {
  const res = await post("/events/e1/holds", { seat: "A1", customer: "ann" });
  assert.equal(res.status, 201);
  assert.deepEqual(res.json, { eventId: "e1", seat: "A1", customer: "ann" });
});

test("the same customer re-holding their seat is fine", async () => {
  await post("/events/e1/holds", { seat: "A2", customer: "ann" });
  const res = await post("/events/e1/holds", { seat: "A2", customer: "ann" });
  assert.equal(res.status, 201);
});

test("a seat held by someone else is 409 seat_taken", async () => {
  await post("/events/e1/holds", { seat: "B1", customer: "ann" });
  const res = await post("/events/e1/holds", { seat: "B1", customer: "bob" });
  console.log("conflict response:", res.status, JSON.stringify(res.json));
  assert.equal(res.status, 409);
  assert.equal(res.json.error.code, "seat_taken");
  assert.deepEqual(res.json.error.details, { seat: "B1" });
});

test("a malformed seat is 422 invalid_request naming the field", async () => {
  const res = await post("/events/e1/holds", { seat: "17", customer: "ann" });
  assert.equal(res.status, 422);
  assert.equal(res.json.error.code, "invalid_request");
  assert.deepEqual(res.json.error.details, { field: "seat" });
});

test("an unknown event is 404 and an unknown route is 404", async () => {
  assert.equal((await post("/events/nope/holds", { seat: "A1", customer: "ann" })).status, 404);
  assert.equal((await post("/something/else", {})).status, 404);
});

test("a body that is not JSON is 400", async () => {
  const res = await post("/events/e1/holds", null, "{not json");
  assert.equal(res.status, 400);
  assert.equal(res.json.error.code, "malformed_json");
});

test("an unexpected bug is 500 and does not leak its message", async () => {
  const res = await post("/events/e1/holds", { seat: "A1", customer: "explode" });
  assert.equal(res.status, 500);
  assert.equal(res.json.error.code, "internal");
  assert.ok(!JSON.stringify(res.json).includes("password"), "internal details leaked to the client");
});

test("a lost race leaves the first holder in place and tells every later customer 409", async () => {
  await post("/events/e1/holds", { seat: "A1", customer: "zed" });
  const statuses = [];
  for (const customer of ["cy", "di"]) {
    statuses.push((await post("/events/e1/holds", { seat: "A1", customer })).status);
  }
  assert.deepEqual(statuses, [409, 409]);
  assert.ok(service.heldSeats("e1").includes("A1"));
});
